/** Portable source schema-2 update checks and opt-in verified staging. Never applies an update. */
public final class ServerUpdates {
    public static final String DEFAULT_MANIFEST="https://www.aosplay.net/updates/stable.json";
    private static final Pattern VERSION=Pattern.compile("v?(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:\\.(0|[1-9][0-9]*))?(?:-([0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*))?(?:\\+[0-9A-Za-z.-]+)?");
    public record Release(String version,String file,List<URI> mirrors,long size,String sha256,String root,boolean required,Long protocol,List<String> preserve,List<String> mirrorDirectories,List<String> remove) {
        public Release{version=version.strip();mirrors=List.copyOf(mirrors);preserve=List.copyOf(preserve);mirrorDirectories=List.copyOf(mirrorDirectories);remove=List.copyOf(remove);if(ServerUpdates.version(version)==null||file.isEmpty()||file.equals(".")||file.equals("..")||!relative(file)||file.contains("/")||file.contains("\\")||mirrors.isEmpty()||size<=0||!sha256.matches("[0-9a-fA-F]{64}")||!relative(root))throw new IllegalArgumentException("Invalid server release");for(var uri:mirrors)url(uri.toString());for(var list:List.of(preserve,mirrorDirectories,remove))for(String path:list)if(path.isEmpty()||!relative(path))throw new IllegalArgumentException("Unsafe release path");sha256=sha256.toLowerCase(Locale.ROOT);}
    }
    private record Version(List<BigInteger> core,List<String> pre) implements Comparable<Version>{
        public int compareTo(Version other){for(int i=0;i<3;i++){int c=core.get(i).compareTo(other.core.get(i));if(c!=0)return c;}if(pre==null||other.pre==null)return pre==other.pre?0:pre==null?1:-1;for(int i=0;i<Math.min(pre.size(),other.pre.size());i++){String a=pre.get(i),b=other.pre.get(i);boolean an=numeric(a),bn=numeric(b);int c=an&&bn?new BigInteger(a).compareTo(new BigInteger(b)):an!=bn?an?-1:1:a.compareTo(b);if(c!=0)return c;}return Integer.compare(pre.size(),other.pre.size());}
    }
    private ServerUpdates(){}
    private static boolean numeric(String s){return s.matches("[0-9]+");}
    private static Version version(String text){if(text==null)return null;var match=VERSION.matcher(text.strip());if(!match.matches())return null;var pre=match.group(4)==null?null:List.of(match.group(4).split("\\."));if(pre!=null&&pre.stream().anyMatch(p->numeric(p)&&p.length()>1&&p.startsWith("0")))return null;return new Version(List.of(new BigInteger(match.group(1)),new BigInteger(match.group(2)),new BigInteger(match.group(3)==null?"0":match.group(3))),pre);}
    public static boolean newer(String candidate,String current){var a=version(candidate);var b=version(current);return a!=null&&b!=null&&a.compareTo(b)>0;}
    /** Scheme/authority validation also applies to every redirect target. */
    public static URI url(String value){URI uri=URI.create(value);String host=uri.getHost(),scheme=uri.getScheme();if(host==null||uri.getRawUserInfo()!=null||uri.getRawFragment()!=null||!("https".equalsIgnoreCase(scheme)||"http".equalsIgnoreCase(scheme)&&(host.equalsIgnoreCase("localhost")||host.equals("127.0.0.1"))))throw new IllegalArgumentException("Update URL requires HTTPS or localhost HTTP");return uri;}
    private static boolean relative(String value){String path=value.replace('\\','/');return path.indexOf(0)<0&&!path.startsWith("/")&&!path.contains(":")&&Arrays.stream(path.split("/",-1)).noneMatch(".."::equals);}
    private static String text(Object value){return value==null?"":String.valueOf(value);}
    private static List<String> paths(Map<?,?> row,String key){Object value=row.get(key);if(value==null)return List.of();if(!(value instanceof List<?> list))throw new IllegalArgumentException("server "+key+" must be paths");var result=new ArrayList<String>();for(Object item:list){if(!(item instanceof String s)||s.isEmpty()||!relative(s))throw new IllegalArgumentException("Unsafe server "+key+" path");result.add(s);}return List.copyOf(result);}
    private static boolean truth(Object value){return value!=null&&!Boolean.FALSE.equals(value)&&!(value instanceof String s&&s.isEmpty())&&!(value instanceof Number n&&n.doubleValue()==0)&&!(value instanceof Collection<?> c&&c.isEmpty())&&!(value instanceof Map<?,?> m&&m.isEmpty());}
    public static Release parse(Object document){
        if(!(document instanceof Map<?,?> root)||!(root.get("schema") instanceof Number n)||n.doubleValue()!=2||!"BattleSpades".equals(root.get("product"))||!(root.get("components") instanceof Map<?,?> components))throw new IllegalArgumentException("Expected BattleSpades schema-2 component manifest");
        Object entry=components.get("server");if(entry==null)return null;if(!(entry instanceof Map<?,?> row))throw new IllegalArgumentException("server component must be an object");
        String v=text(row.get("version")).strip(),file=text(row.get("package")),hash=text(row.get("sha256")),hint=text(row.get("root"));if(version(v)==null)throw new IllegalArgumentException("server version is not semver");if(file.isEmpty()||file.equals(".")||file.equals("..")||file.chars().anyMatch(c->c=='/'||c=='\\'||c==':'||c==0))throw new IllegalArgumentException("server package must be a file name");if(!(row.get("urls") instanceof List<?> urls)||urls.isEmpty())throw new IllegalArgumentException("server urls must list mirrors");var mirrors=new ArrayList<URI>();for(Object item:urls){if(!(item instanceof String s))throw new IllegalArgumentException("server mirror must be text");mirrors.add(url(s));}if(!(row.get("size") instanceof Long size)||size<=0)throw new IllegalArgumentException("server size must be a positive integer");if(!hash.matches("[0-9a-fA-F]{64}"))throw new IllegalArgumentException("server sha256 must be 64 hex digits");if(!relative(hint)||hint.indexOf('\0')>=0)throw new IllegalArgumentException("Unsafe archive root");return new Release(v,file,mirrors,size,hash.toLowerCase(Locale.ROOT),hint,truth(row.get("required"))||truth(root.get("required")),row.get("protocol") instanceof Long p?p:null,paths(row,"preserve"),paths(row,"mirror_directories"),paths(row,"remove"));
    }
    private static final class Body implements HttpResponse.BodySubscriber<byte[]> {
        final CompletableFuture<byte[]> result=new CompletableFuture<>();final ByteArrayOutputStream data=new ByteArrayOutputStream();final int limit;Flow.Subscription subscription;
        Body(int limit){this.limit=limit;}public CompletionStage<byte[]> getBody(){return result;}public void onSubscribe(Flow.Subscription s){subscription=s;s.request(Long.MAX_VALUE);}public void onNext(List<ByteBuffer> buffers){if(result.isDone())return;for(var buffer:buffers){if(buffer.remaining()>limit-data.size()){subscription.cancel();result.completeExceptionally(new IOException("Update manifest exceeds 1 MiB"));return;}byte[] bytes=new byte[buffer.remaining()];buffer.get(bytes);data.writeBytes(bytes);}}public void onError(Throwable error){result.completeExceptionally(error);}public void onComplete(){result.complete(data.toByteArray());}
    }
    private static HttpClient client(){return HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(6)).followRedirects(HttpClient.Redirect.NEVER).build();}
    private static HttpRequest request(URI uri,int seconds){return HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(seconds)).header("User-Agent","BattleSpades-Server-Update").header("Cache-Control","no-cache").GET().build();}
    private static URI redirect(URI from,HttpResponse<?> response)throws IOException{String location=response.headers().firstValue("Location").orElseThrow(()->new IOException("Update redirect has no location"));try{return url(from.resolve(location).toString());}catch(IllegalArgumentException bad){throw new IOException("Unsafe update redirect",bad);}}
    public static Release check(String current,String manifest)throws IOException,InterruptedException{
        try(var client=client()){URI uri=url(manifest);for(int redirects=0;redirects<6;redirects++){var pending=client.sendAsync(request(uri,6),_ ->new Body(1024*1024));HttpResponse<byte[]> response;try{response=pending.get(6,TimeUnit.SECONDS);}catch(ExecutionException|TimeoutException failed){pending.cancel(true);client.shutdownNow();throw new IOException("Manifest request failed",failed);}catch(InterruptedException interrupted){pending.cancel(true);client.shutdownNow();throw interrupted;}if(response.statusCode()>=300&&response.statusCode()<400){uri=redirect(uri,response);continue;}if(response.statusCode()!=200)throw new IOException("Manifest HTTP "+response.statusCode());String text;try{text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(response.body())).toString();}catch(CharacterCodingException invalid){throw new IllegalArgumentException("Manifest is not UTF-8 JSON",invalid);}Release release=parse(MetadataDocument.json(text));return release!=null&&newer(release.version(),current)?release:null;}throw new IOException("Too many update redirects");}
    }
    /** Daemon advisory work follows the source's nonblocking startup/offline behavior. */
    public static Thread background(String current,String manifest,Consumer<String> info,Consumer<String> warning,Consumer<String> debug){return Thread.ofPlatform().daemon().name("server-update-check").start(()->{try{Release release=check(current,manifest);if(release==null)info.accept("BattleSpades server "+current+" is up to date");else warning.accept("New BattleSpades server version "+release.version()+" available (current "+current+")"+(release.required()?" - REQUIRED":"")+". Run --update to download and stage it.");}catch(IllegalArgumentException invalid){warning.accept("Invalid update manifest: "+invalid.getMessage());}catch(IOException|InterruptedException offline){if(offline instanceof InterruptedException)Thread.currentThread().interrupt();debug.accept("Update check skipped: "+offline.getMessage());}});}
    private static void cancelBody(InputStream input){try{input.close();}catch(IOException ignored){/* Timeout is reported by the reading worker. */}}
    private static String hash(Path file)throws IOException{var digest=digest();try(var in=Files.newInputStream(file)){byte[] data=new byte[65536];for(int n;(n=in.read(data))!=-1;)digest.update(data,0,n);}return HexFormat.of().formatHex(digest.digest());}
    private static MessageDigest digest(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
    public static Path download(Release release,Path directory,Consumer<String> out)throws IOException,InterruptedException{
        Files.createDirectories(directory);Path destination=directory.resolve(release.file()),partial=directory.resolve(release.file()+".partial");if(Files.isRegularFile(destination,LinkOption.NOFOLLOW_LINKS)&&Files.size(destination)==release.size()&&hash(destination).equals(release.sha256())){out.accept("Using already verified "+release.file());return destination;}Files.deleteIfExists(destination);var failures=new ArrayList<IOException>();
        try(var client=client()){for(URI mirror:release.mirrors()){
            out.accept("Downloading "+release.file()+" from "+mirror);URI uri=mirror;
            try{for(int redirects=0;;redirects++){if(redirects>=6)throw new IOException("Too many download redirects");
                // An asynchronous body deadline covers a peer that sends headers but stalls the download.
                var pending=client.sendAsync(request(uri,30),HttpResponse.BodyHandlers.ofInputStream());HttpResponse<InputStream> response;try{response=pending.get(30,TimeUnit.SECONDS);}catch(TimeoutException|InterruptedException failed){pending.cancel(true);throw failed;}
                try(var input=response.body()){if(response.statusCode()>=300&&response.statusCode()<400){uri=redirect(uri,response);continue;}if(response.statusCode()!=200)throw new IOException("Package HTTP "+response.statusCode());
                    var digest=digest();long count=0;Files.deleteIfExists(partial);try(var output=Files.newOutputStream(partial,StandardOpenOption.CREATE_NEW)){byte[] data=new byte[65536];long deadline=System.nanoTime()+30000000000L;
                        // Closing a body from the deadline task unblocks a stalled read without owner-thread I/O.
                        var timer=Executors.newSingleThreadScheduledExecutor(Thread.ofPlatform().daemon().name("update-body-timeout").factory());var timeout=timer.schedule(()->cancelBody(input),30,TimeUnit.SECONDS);
                        try{for(int n;(n=input.read(data))!=-1;){if(System.nanoTime()>deadline)throw new IOException("Package download timed out");if(n>release.size()-count)throw new IOException("Package exceeds declared size");count+=n;digest.update(data,0,n);output.write(data,0,n);}}finally{timeout.cancel(false);timer.shutdownNow();}
                    }if(count!=release.size())throw new IOException("Package size mismatch");if(!HexFormat.of().formatHex(digest.digest()).equals(release.sha256()))throw new IOException("Package SHA-256 mismatch");Files.move(partial,destination,StandardCopyOption.REPLACE_EXISTING);return destination;
                }
            }}catch(IOException|ExecutionException|TimeoutException|IllegalArgumentException error){Files.deleteIfExists(partial);var failure=new IOException("Mirror failed: "+mirror,error);failures.add(failure);out.accept(failure.getMessage());}catch(InterruptedException interrupted){Files.deleteIfExists(partial);throw interrupted;}
        }}var failure=new IOException("Every package mirror failed");failures.forEach(failure::addSuppressed);throw failure;
    }
    private static void deleteTree(Path path)throws IOException{if(!Files.exists(path,LinkOption.NOFOLLOW_LINKS))return;try(var files=Files.walk(path)){for(Path file:files.sorted(Comparator.reverseOrder()).toList())Files.delete(file);}}
    private static Path packageRoot(Path payload,String hint)throws IOException{if(!hint.isEmpty()){Path candidate=payload.resolve(hint.replace('\\','/'));if(marker(candidate))return candidate;}var queue=new ArrayDeque<Map.Entry<Path,Integer>>();queue.add(Map.entry(payload,0));while(!queue.isEmpty()){var item=queue.remove();if(marker(item.getKey()))return item.getKey();if(item.getValue()<3)try(var files=Files.list(item.getKey())){files.filter(Files::isDirectory).sorted().forEach(p->queue.add(Map.entry(p,item.getValue()+1)));}}throw new IOException("Package has no VERSION or BattleSpades.exe");}
    private static boolean marker(Path directory){return Files.isRegularFile(directory.resolve("VERSION"))||Files.isRegularFile(directory.resolve("BattleSpades.exe"));}
    public static Path stage(Path root,Release release,Path archive)throws IOException{
        Path staging=root.resolve("update/staging"),target=staging.resolve("server-"+release.version()),extracting=staging.resolve("server-"+release.version()+".extracting"),payload=extracting.resolve("payload");deleteTree(extracting);Files.createDirectories(payload);Path base=payload.toAbsolutePath().normalize();
        try{long total=0;int entries=0;try(var zip=new ZipInputStream(Files.newInputStream(archive))){for(ZipEntry entry;(entry=zip.getNextEntry())!=null;){String name=entry.getName().replace('\\','/');Path file=base.resolve(name).normalize();if(!relative(name)||!file.startsWith(base)||++entries>100000)throw new IOException("Unsafe or excessive archive entries");if(entry.isDirectory()){Files.createDirectories(file);continue;}Files.createDirectories(file.getParent());try(var output=Files.newOutputStream(file,StandardOpenOption.CREATE_NEW)){byte[] data=new byte[65536];for(int n;(n=zip.read(data))!=-1;){total+=n;if(total>2L*1024*1024*1024)throw new IOException("Extracted package exceeds 2 GiB");output.write(data,0,n);}}}}
            Path selected=packageRoot(base,release.root());String relative=base.relativize(selected).toString().replace('\\','/');var marker=new LinkedHashMap<String,Object>();marker.put("schema",2);marker.put("component","server");marker.put("version",release.version());marker.put("sha256",release.sha256());marker.put("root",relative);marker.put("preserve",release.preserve());marker.put("mirror_directories",release.mirrorDirectories());marker.put("remove",release.remove());Files.writeString(extracting.resolve("staged.json"),JsonData.encode(marker),StandardOpenOption.CREATE_NEW);deleteTree(target);Files.move(extracting,target);return target.resolve("payload").resolve(relative);
        }catch(IOException|RuntimeException failure){try{deleteTree(extracting);}catch(IOException cleanup){failure.addSuppressed(cleanup);}throw failure;}
    }
    public static int run(Path root,String current,String manifest,Consumer<String> out){try{var release=check(current,manifest);if(release==null){out.accept("BattleSpades server "+current+" is up to date.");return 0;}out.accept("New server version "+release.version()+" available (current "+current+").");Path archive=download(release,root.resolve("update/download"),out),staged=stage(root,release,archive);Files.delete(archive);out.accept("Verified and staged at: "+staged);out.accept("Installation files were not replaced. Stop the server and review the package and preserve paths before applying it.");return 0;}catch(IOException|IllegalArgumentException|InterruptedException failure){if(failure instanceof InterruptedException)Thread.currentThread().interrupt();out.accept("Update failed: "+failure.getMessage());return 1;}}
}
